pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;

    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        address owner = address(this);

        vm.prank(owner);
        c.NETM();

        uint256 bal = c.balanceOf(owner);
        uint256 distributed = c.totalDistributed();

        assertTrue(bal == distributed);
    }
}
